package main

import (
	"encoding/json"
	"io"
	"log"
	"net/http"
	"strings"
)

type mensaje struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

type herramienta struct {
	Function struct {
		Name      string `json:"name"`
		Arguments string `json:"arguments"`
	} `json:"function"`
}

type peticion struct {
	Messages  []mensaje     `json:"messages"`
	Tools     []interface{} `json:"tools"`
	MaxTokens int           `json:"max_tokens"`
}

func main() {
	http.HandleFunc("/v1/chat/completions", func(w http.ResponseWriter, r *http.Request) {
		raw, _ := io.ReadAll(r.Body)
		var p peticion
		_ = json.Unmarshal(raw, &p)
		w.Header().Set("Content-Type", "application/json")

		respuesta := func(resp map[string]interface{}) {
			body, _ := json.Marshal(map[string]interface{}{
				"choices": []map[string]interface{}{{"message": resp}},
				"usage":   map[string]interface{}{"prompt_tokens": 100, "completion_tokens": 50, "total_tokens": 150},
			})
			w.Write(body)
		}

		ultimo := ""
		if n := len(p.Messages); n > 0 {
			ultimo = p.Messages[n-1].Content
		}

		if len(p.Tools) == 0 {
			// FASE 1: clasificador de módulos
			respuesta(map[string]interface{}{"role": "assistant", "content": "customer_information,invoice"})
			return
		}
		if strings.Contains(ultimo, "Continúa la tarea") {
			jsonDef := `{"title":"Ventas por cliente (prueba IA)","sql":"SELECT c.customer_name AS cliente, COUNT(i.id) AS facturas, IFNULL(SUM(i.total_amount),0) AS total FROM customer_information c LEFT JOIN invoice i ON i.customer_id = c.customer_id GROUP BY c.customer_name ORDER BY total DESC","columns":[{"key":"cliente","label":"Cliente"},{"key":"facturas","label":"Facturas"},{"key":"total","label":"Total"}],"totals":["total"]}`
			respuesta(map[string]interface{}{"role": "assistant", "content": jsonDef})
			return
		}
		// FASE 2, primer paso: pedir una consulta a la base.
		toolCall := map[string]interface{}{
			"id": "call-fake-1", "type": "function",
			"function": map[string]interface{}{
				"name": "db_query",
				"arguments": `{"sql":"SELECT customer_name, customer_email FROM customer_information LIMIT 5"}`,
			},
		}
		respuesta(map[string]interface{}{"role": "assistant", "content": "", "tool_calls": []interface{}{toolCall}})
	})
	log.Fatal(http.ListenAndServe("127.0.0.1:8099", nil))
}
```

