+package main
+
+// proveedor-falso — servidor OpenAI-compatible de VERIFICACIÓN en local.
+// Reemplaza al proveedor real en la prueba end-to-end del asistente de
+// informes. Nada de esto vive en producción: se borra su directorio al terminar.
+//
+// Contrato utilizado por el bucle agéntico de ERPGo:
+//   - FASE 1 (clasificación): petición SIN "tools" → responde content con las
+//     claves de módulos separadas por comas.
+//   - FASE 2 (bucle agéntico): petición CON tools. El primer paso responde un
+//     tool_call a db_query; cuando vuelve el resultado (la petición trae una
+//     última mensagem "…Continúa la tarea…"), responde el JSON de la definición.
+
+import (
+	"encoding/json"
+	"io"
+	"log"
+	"net/http"
+	"strings"
+)
+
+type mensaje struct {
+	Role    string `json:"role"`
+	Content string `json:"content"`
+}
+
+type peticion struct {
+	Messages []mensaje     `json:"messages"`
+	Tools    []interface{} `json:"tools"`
+}
+
+func main() {
+	http.HandleFunc("/v1/chat/completions", func(w http.ResponseWriter, r *http.Request) {
+		raw, _ := io.ReadAll(r.Body)
+		var p peticion
+		_ = json.Unmarshal(raw, &p)
+		w.Header().Set("Content-Type", "application/json")
+
+		respuesta := func(contenido string, toolCalls []interface{}) {
+			msg := map[string]interface{}{"role": "assistant", "content": contenido}
+			if len(toolCalls) > 0 {
+				msg["tool_calls"] = toolCalls
+			}
+			body, _ := json.Marshal(map[string]interface{}{
+				"choices": []map[string]interface{}{{"message": msg, "finish_reason": "stop"}},
+				"usage":   map[string]interface{}{"prompt_tokens": 120, "completion_tokens": 60, "total_tokens": 180},
+			})
+			_, _ = w.Write(body)
+		}
+
+		ultimo := ""
+		if n := len(p.Messages); n > 0 {
+			ultimo = p.Messages[n-1].Content
+		}
+
+		if len(p.Tools) == 0 {
+			// FASE 1 — clasificador: dos módulos cualesquiera.
+			respuesta("customer_information,invoice", nil)
+			return
+		}
+		if strings.Contains(ultimo, "Continúa la tarea") {
+			// FASE 2, segundo paso: la DEFINICIÓN del informe.
+			definicion := `{"title":"Ventas por cliente (prueba IA)","sql":"SELECT c.customer_name AS cliente, COUNT(i.id) AS facturas, IFNULL(SUM(i.total_amount),0) AS total FROM customer_information c LEFT JOIN invoice i ON i.customer_id = c.customer_id GROUP BY c.customer_name ORDER BY total DESC","columns":[{"key":"cliente","label":"Cliente"},{"key":"facturas","label":"Facturas"},{"key":"total","label":"Total"}],"totals":["total"]}`
+			respuesta(definicion, nil)
+			return
+		}
+		// FASE 2, primer paso: pedir una consulta a la base con db_query.
+		respuesta("", []interface{}{map[string]interface{}{
+			"id": "call-fake-1", "type": "function",
+			"function": map[string]interface{}{
+				"name": "db_query",
+				"arguments": `{"sql":"SELECT customer_name, customer_email FROM customer_information LIMIT 5"}`,
+			},
+		}})
+	})
+	log.Fatal(http.ListenAndServe("127.0.0.1:8099", nil))
+}
