+func TestElTotalDeUnResultadoVacioEsCeroSinWarning(t *testing.T) {
+	s, db := basePrueba(t)
+	crearTablaReportTemplatePrueba(t, db)
+	if _, err := db.Exec(`CREATE TABLE IF NOT EXISTS ventas_vacias (
